{
  "title": "To Ship or Not to Ship: Engineering Ethics Case Report",
  "overview": "Write an individual report analysing the ethical decisions stakeholders face in Rachel’s quality-assurance scenario. Evaluate whether shipping servers with known defects is ethical, explain how to decide whether to ship, and recommend what Rachel should do. Support all arguments with reputable evidence, including external case studies, and consider the consequences for all affected stakeholders.",
  "deliverables": [
    "A written report with an approximately 150-word abstract, introduction, body and conclusion.",
    "A justified recommendation for Rachel on whether and under what conditions the servers should be shipped."
  ],
  "format": {
    "length": "Maximum 1,500 words for the introduction, body and conclusion combined; abstract is approximately 150 words and excluded from the limit. References and figures are also excluded.",
    "structure": "Include an abstract, introduction, body and conclusion. Body headings are optional; the body may be organised freely.",
    "other": "Figures and tables are permitted. Use a consistent, established referencing style, such as Harvard or IEEE."
  },
  "requirements": [
    {
      "id": "R1",
      "text": "Analyse the scenario in which Rachel, a quality-assurance engineer, has limited time to test servers and must decide whether to ship products with known defects. Address the distinction between possible physical harm and a higher likelihood of failure causing customer data loss."
    },
    {
      "id": "R2",
      "text": "Discuss whether this is an ethical way to conduct business and how Rachel should determine when a product with known defects may be shipped."
    },
    {
      "id": "R3",
      "text": "Evaluate the decision trade-offs, including the time and testing constraints, competitive pressure, company revenue and growth, Rachel’s employment interests, and the potential for large-scale testing to inform future safety improvements."
    },
    {
      "id": "R4",
      "text": "Address the government health department contract and the potential for server failure to cause improper health administration or catastrophic consequences for hospitals, emergency services, and the business."
    },
    {
      "id": "R5",
      "text": "Identify and discuss relevant ethical issues and stakeholder perspectives, considering arguments and consequences both for and against possible decisions."
    },
    {
      "id": "R6",
      "text": "Research the ethical considerations thoroughly and support all arguments with reputable evidence and external case studies. A conclusion based only on compliance with law or regulation is insufficient."
    },
    {
      "id": "R7",
      "text": "Conclude with a holistic, evidence-based and justified recommended course of action for Rachel."
    }
  ]
}
